CREATE OR REPLACE FUNCTION auto_confirm_user(user_id UUID) RETURNS JSON LANGUAGE plpgsql SECURITY DEFINER AS $func$ BEGIN UPDATE auth.users SET confirmed_at = NOW(), updated_at = NOW() WHERE id = user_id; IF NOT FOUND THEN RETURN json_build_object('status', 'error', 'message', 'User not found'); END IF; RETURN json_build_object('status', 'success'); END; $func$;